import{_ as o,H as t,f as d,i as a}from"./chunks/framework.BauLNg70.js";const p=JSON.parse('{"title":"Host API changelog","description":"","frontmatter":{},"headers":[],"relativePath":"host-api-changelog.md","filePath":"host-api-changelog.md"}'),s={name:"host-api-changelog.md"};function c(i,e,r,n,l,h){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="host-api-changelog" tabindex="-1">Host API changelog <a class="header-anchor" href="#host-api-changelog" aria-label="Permalink to &quot;Host API changelog&quot;">​</a></h1><p>SemVer versioning of the <code>HostBridge</code> that Snake Classic mods see.</p><blockquote><p><strong>Contract</strong>: a mod&#39;s manifest declares <code>requires.hostApi: &#39;^1.0.0&#39;</code>. The loader rejects mods whose constraint doesn&#39;t match the current game version (<code>incompatible</code> state, mod doesn&#39;t activate).</p></blockquote><hr><h2 id="v1-0-0-—-launch-2026-xx-xx" tabindex="-1">v1.0.0 — Launch (2026-XX-XX) <a class="header-anchor" href="#v1-0-0-—-launch-2026-xx-xx" aria-label="Permalink to &quot;v1.0.0 — Launch (2026-XX-XX)&quot;">​</a></h2><p>Initial surface exposed to the modder:</p><ul><li><code>host.callHostFn(name, args)</code> — invoke host functions registered by the game for mods (<code>togglePowerUp</code>, <code>setPowerUpSpawnChance</code>, <code>setSpeedBase</code>, <code>setSpeedProgression</code>).</li><li><code>host.subscribeEvent(name, cb)</code> — subscribe to game events listed in <code>policy.surfaces.events.subscribe</code>. Snake Classic exposes: <code>GAME_STARTED</code>, <code>POWERUP_SPAWNED</code>, <code>GAME_OVER</code>, <code>SCORE_INCREASED</code>, <code>SNAKE_DIED</code>.</li><li><code>host.registerHook(name, fn)</code> — register mod lifecycle hooks (<code>onActivate</code>, <code>onDeactivate</code>).</li><li><code>host.state.read(path)</code> — <strong>read-only</strong> game state lookup by canonical path. Snake Classic exposes these 7 paths (<code>SCREAMING_SNAKE_CASE__DOUBLE_UNDERSCORE</code> convention of the game&#39;s state store): <ul><li><code>GAME_DATA__RUN__SCORE__CURRENT</code> — current game score.</li><li><code>GAME_DATA__RUN__SCORE__MULTIPLIER</code> — active multiplier.</li><li><code>GAME_DATA__RUN__SPEED__LEVEL</code> — speed level.</li><li><code>GAME_DATA__RUN__SNAKE__LENGTH</code> — snake length.</li><li><code>GAME_DATA__RUN__POWERUP__ACTIVE</code> — active power-up (or null).</li><li><code>GAME_DATA__RUN__POWERUP__ACTIVE_VARIANT</code> — active variant.</li><li><code>GAME_DATA__APP_SYNC__PROGRESS__HIGH_SCORE</code> — persisted high score.</li></ul></li><li><code>host.storage.{get,set,delete,keys}(...)</code> — per-mod isolated storage, quota declared in <code>permissions.storage.quotaKb</code>.</li><li><code>host.i18n.{register,t}(...)</code> — mod translations (if it declares <code>permissions.i18n</code>).</li><li><code>host.log.{debug,info,warn,error}(...)</code> — logger (doesn&#39;t affect the game&#39;s error bus).</li><li><code>host.analytics.track(name, props)</code> — custom events declared in <code>mod.json#analytics.events</code>.</li><li><code>host.registerSettingsTab(descriptor)</code> — declarative tabs at <code>Settings → Mods → &lt;your tab&gt;</code>. UI component catalog at <a href="/mod-portal-snake-classic/storybook/">/storybook/</a>.</li><li><code>host.registerPowerUp(def)</code> — register new power-ups (if you declare <code>permissions.powerups.actions: [&#39;register&#39;]</code>).</li><li><code>host.registerAsset(kind, id, source)</code> — substitute images / audio / fonts (if you declare <code>permissions.assets</code>).</li></ul><h3 id="events-mod-framework-emitted-by-the-runtime" tabindex="-1">Events <code>mod.framework.*</code> emitted by the runtime <a class="header-anchor" href="#events-mod-framework-emitted-by-the-runtime" aria-label="Permalink to &quot;Events `mod.framework.*` emitted by the runtime&quot;">​</a></h3><p>20 canonical automatic events (no modder participation). Full list at <a href="https://github.com/leteoworks/my-game-fw/blob/main/src/modules/mod-runtime/telemetry/framework-events.ts" target="_blank" rel="noreferrer">framework-events.ts</a>. Summary:</p><ul><li><strong>Discovery + lifecycle</strong> (8): <code>discovered</code>, <code>validated_ok</code>, <code>upgrade</code>, <code>removed</code>, <code>activated</code>, <code>deactivated</code>, <code>permission_prompt_shown</code>, <code>permission_decision</code>, <code>session_summary</code>.</li><li><strong>Engagement</strong> (2): <code>engagement_tick</code>, <code>first_use_ever</code>.</li><li><strong>Errors + limits</strong> (3): <code>fault_summary</code>, <code>quota_hit</code>, <code>api_violation</code>.</li><li><strong>Performance</strong> (7): <code>perf.frame_impact</code>, <code>perf.cpu_budget</code>, <code>perf.memory_high_water</code>, <code>perf.hook_slow</code>, <code>perf.long_task_attributed</code>, <code>perf.budget_exceeded</code>, <code>perf.throttled</code>.</li></ul><h3 id="not-available-in-v1-0-0" tabindex="-1">NOT available in v1.0.0 <a class="header-anchor" href="#not-available-in-v1-0-0" aria-label="Permalink to &quot;NOT available in v1.0.0&quot;">​</a></h3><ul><li><code>fetch</code> or <code>XMLHttpRequest</code> directly — the sandbox blocks them.</li><li><code>window</code>, <code>document</code>, <code>localStorage</code>.</li><li><code>host.state.write(...)</code> — Snake Classic v1.0.0 <strong>only exposes reads</strong> (<code>state.read</code>). If you need to modify state, do it via events (<code>host.subscribeEvent</code> + <code>host.callHostFn</code> that the game exposes as a contract).</li><li>Arbitrary networking — <code>host.http.request</code> exists but only if you declare <code>permissions.network</code> and the host is in the allowlist.</li><li>Backend clients (leaderboards, save sync) — gated by <code>permissions.backend-client</code> (not exposed in Snake Classic v1.0.0).</li></ul><hr><h2 id="versioning-policy" tabindex="-1">Versioning policy <a class="header-anchor" href="#versioning-policy" aria-label="Permalink to &quot;Versioning policy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Change</th><th>SemVer bump</th></tr></thead><tbody><tr><td>Add new helper to <code>host.*</code></td><td>MINOR</td></tr><tr><td>Add surface declared in <code>policy.ts</code></td><td>MINOR (existing mods don&#39;t request, don&#39;t break)</td></tr><tr><td>Change shape of an existing helper</td><td>MAJOR (breaks mods using it)</td></tr><tr><td>Remove a helper</td><td>MAJOR</td></tr><tr><td>Add new error code</td><td>MINOR</td></tr><tr><td>Change existing error code</td><td>MAJOR</td></tr><tr><td>Game-only manifest changes (not exposed to the mod)</td><td>no bump</td></tr></tbody></table><p>Any MAJOR bump requires documenting the migration in this page before merging the change to the runtime.</p><hr><h2 id="cross-links" tabindex="-1">Cross-links <a class="header-anchor" href="#cross-links" aria-label="Permalink to &quot;Cross-links&quot;">​</a></h2><ul><li><a href="/mod-portal-snake-classic/api-reference">api-reference</a></li><li><a href="/mod-portal-snake-classic/manifest-format">manifest-format</a></li><li><a href="https://github.com/leteoworks/my-game-fw/blob/main/docs/mods/philosophy.md" target="_blank" rel="noreferrer">System philosophy (monorepo)</a></li></ul>',19)])])}const g=o(s,[["render",c]]);export{p as __pageData,g as default};
